import React, {ReactElement, useRef} from 'react';
import RBSheet from 'react-native-raw-bottom-sheet';
import AppText from '@components/app-text/app-text';
import styles from './language-chooser-component.styles';
import {FlatList, TouchableOpacity, View} from 'react-native';
import {LanguageChooserComponentProps} from './language-chooser-component.props';
import Globe from '../../assets/images/globe.svg';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { useAppState } from '@store/AppContext.tsx';

interface LanguageOption {
  label: string;
  value: string;
}

interface LanguageListData {
  data: LanguageOption[];
}

const jsonData = require('../../assets/json/languages.json') as LanguageListData;

const LanguageChooserComponent = (props: LanguageChooserComponentProps) => {
  const refRBSheet = useRef();
  const { language, showLanguage } = useAppState();
  const selectedLanguageLabel = showLanguage();

  const renderItem = ({item, index}: {item: LanguageOption; index: number}) => {
    const isSelected = language === item.label;
    return (
      <View
        style={[
          index != jsonData.data.length-1 ? styles.itemContainer : {},
          styles.itemContainerRadius
        ]}>
        <TouchableOpacity
          onPress={() => languageCallbackFunction(item)}
          style={styles.itemBtnContainer}>
          <AppText
            size={'xsmall'}
            style={[styles.itemText, {
              color: isSelected ? '#00E0C8' : '#0F1617',
              fontWeight: isSelected ? '700' : '300'
            }]}
          >
            {item.value}
          </AppText>
        </TouchableOpacity>
      </View>
    );
  };

  const insets = useSafeAreaInsets();

  const languageBottomSheet = (): ReactElement => {
    return (
      <RBSheet
        ref={refRBSheet}
        height={!$isTablet?640:640+insets.bottom}
        closeOnDragDown={true}
        closeOnPressMask={true}
        customStyles={{
          container: styles.rbsheetContainer,
        }}
      >
        <View
          style={styles.listContainer}
        >
          <AppText
            size='medium'
            style={styles.changeLangContainer}
          >
            {$i18n.t('setting.changeLanguage')}
          </AppText>
          <FlatList
            data={jsonData.data}
            keyExtractor={(item, index) => index}
            renderItem={renderItem}
            showsVerticalScrollIndicator={false}
          />
        </View>
        <TouchableOpacity
          onPress={() => refRBSheet.current.close()}
          style={[styles.cancelBtnContainer]} >
          <AppText
            size='small'
            style={{
              alignSelf: 'center'
            }}
          >
            {$i18n.t('cancel')}
          </AppText>
        </TouchableOpacity>
      </RBSheet>
    );
  };

  const languageCallbackFunction = (item: LanguageOption): void => {
    props.onChangeLanguageCallback(item);
    refRBSheet.current.close();
  };

  return (
    <TouchableOpacity
      onPress={() => refRBSheet.current.open()}
      style={[
        styles.defaultContainer,
        props?.style,
      ]}>
      <Globe width={16} height={16}/>
      <AppText
        size='xsmall'
        style={styles.langText}>
        {selectedLanguageLabel}
      </AppText>
      {languageBottomSheet()}
    </TouchableOpacity>
  );
};

export default LanguageChooserComponent;

