      console.log('logout-modal handleLogout error=', e);
      showLogoutErrorToast($i18n.t('try_later'));
    } finally {
      isConfirmingLogoutRef.current = false;
    }
  }, [getAuthLogoutErrorMessage, logout, setLogoutModal, showLogoutErrorToast]);

